No project in the working directory, so here it is as a standalone router (not run against a database):

```js
const express = require('express');
const { Pool } = require('pg');

const pool = new Pool(); // reads PG* env vars
const router = express.Router();

const encodeCursor = (ts, id) =>
  Buffer.from(JSON.stringify([ts, String(id)])).toString('base64url');

function decodeCursor(s) {
  try {
    const [ts, id] = JSON.parse(Buffer.from(s, 'base64url').toString());
    return typeof ts === 'string' && typeof id === 'string' ? [ts, id] : null;
  } catch {
    return null;
  }
}

// GET /orders?limit=20&cursor=<next_cursor from previous page>
router.get('/orders', async (req, res, next) => {
  const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 20, 1), 100);

  let after = null;
  if (req.query.cursor !== undefined) {
    after = decodeCursor(req.query.cursor);
    if (!after) return res.status(400).json({ error: 'invalid cursor' });
  }

  try {
    // created_at::text keeps microseconds; a JS Date would truncate to ms and skip/repeat rows
    const { rows } = await pool.query(
      `SELECT *, created_at::text AS cursor_ts
         FROM orders
        ${after ? 'WHERE (created_at, id) < ($2, $3)' : ''}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      [limit + 1, ...(after ?? [])] // one extra row tells us if there's a next page
    );

    const page = rows.slice(0, limit);
    const last = page[page.length - 1];
    res.json({
      data: page.map(({ cursor_ts, ...order }) => order),
      next_cursor: rows.length > limit ? encodeCursor(last.cursor_ts, last.id) : null,
    });
  } catch (err) {
    // class 22 = data exception: a well-formed cursor carrying a garbage timestamp/id
    if (err.code?.startsWith('22')) return res.status(400).json({ error: 'invalid cursor' });
    next(err);
  }
});

module.exports = router;
```

It needs this index to be fast:

```sql
CREATE INDEX orders_created_at_id_idx ON orders (created_at DESC, id DESC);
```

- **Order:** newest first; the client passes `next_cursor` back as `cursor` until it comes back `null`.
- **Limit:** defaults to 20 and is clamped to 1–100.
- **Skipped:** auth and per-user scoping, so as written this returns everyone's orders. Add `AND user_id = $n` (and lead the index with `user_id`) before exposing it.
- **Skipped:** backward paging and total counts; add them when a client actually needs them.
